source_rows=[('nccp','NCCP 00243 v7: crizotinib monotherapy',N),('smpc','EMA Xalkori product information: adult NSCLC and patient leaflet',S),('classification','NCCP SACT nausea/vomiting classification V6, oral Tables 5 and 8',C),('antiemetic','NCCP NCIS Medical Oncology antiemetics V8 (2025)',A),('profile1007','PROFILE 1007: previously treated ALK NSCLC (2013)',T+'23724913/'),('profile1007-os','PROFILE 1007 final OS: 2016 primary conference abstract','https://ascopubs.org/doi/10.1200/JCO.2016.34.15_suppl.9066'),('profile1014','PROFILE 1014: first-line ALK NSCLC (2014)',T+'25470694/'),('profile1014-os','PROFILE 1014 final OS (2018)',T+'29768118/'),('profile1001','PROFILE 1001 ROS1 update, including OS (2019)',T+'30980071/')]
