for id,label,detail,tier in [('vision','Vision changes and severe visual loss','Report changes in vision; severe visual loss requires urgent ophthalmological assessment and treatment interruption during evaluation.','serious'),('liver','Liver injury','Hepatotoxicity can be serious or fatal. Weekly early liver tests and urgent reporting of jaundice/dark urine are important.','serious'),('ild','Interstitial lung disease / pneumonitis','New or worsening cough or breathlessness needs urgent assessment. Treatment-related lung inflammation can be serious or fatal.','serious'),('cardiac','Slow pulse, QT prolongation and heart failure','Fainting, palpitations, breathlessness, oedema or rapid weight gain need prompt review. Medicines and electrolyte changes can increase risk.','serious'),('renal','Kidney injury','Kidney function can worsen; report reduced urine or dehydration.','serious'),('gi_perforation','Gastrointestinal perforation','Severe abdominal pain needs urgent assessment; bowel perforation has been reported.','serious'),('counts','Low blood counts and infection','Neutropenia/leukopenia can occur. Fever, shivering or sudden illness needs prompt contact.','serious'),('gi','Nausea, vomiting and bowel symptoms','A tailored prevention/rescue plan is needed for nausea, vomiting, diarrhoea or constipation; report poor intake and persistent symptoms.','important'),('daily_life','Swelling, fatigue, nerve and skin symptoms','Oedema, tiredness, neuropathy, rash and sun sensitivity can affect daily life; report changes and use sun protection.','important'),('reproduction','Pregnancy, breastfeeding and fertility','Potential fetal harm and impaired fertility. Discuss preservation; effective contraception during and ≥90 days after treatment; oral contraception may be less effective. Avoid breastfeeding during treatment.','important')]:profile['risks'].append({'id':id,'label':label,'detail':detail,'tier':tier,'source_url':S})
